//
// -------------------------------------------------------------------------
/// Load action at a load handling point
TYPE LoadActionEnum :
(
  /// No action
  NONE := 0,
  /// MR picks the load
  PICK := 1,
  /// MR drops the load
  DROP := 2
);
END_TYPE

