{attribute 'qualified_only'}
// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      RequestStatusEnum
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    Status of a request
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
/// Status of a request
TYPE RequestStatusEnum :
(
  /// No status (request unknown or not yet reported)
  NONE := 0,
  /// The request is pending and has not yet been executed
  PENDING := 1,
  /// The request is currently being executed
  RUNNING := 2,
  /// The request is paused
  PAUSED := 3,
  /// The request has been finished successfully
  FINISHED := 4,
  /// The request could not be finished
  FAILED := 5
);
END_TYPE

{attribute 'qualified_only'}
// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      RequestTypeEnum
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    Type of a request (requestType)
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
/// Type of a request (requestType)
TYPE RequestTypeEnum :
(
  /// Unknown request type
  UNKNOWN := 0,
  /// Request access
  REQUEST_ACCESS := 1,
  /// Request exit
  REQUEST_EXIT := 2,
  /// Request load transfer
  REQUEST_LOAD_TRANSFER := 3,
  /// Release occupancy
  REQUEST_RELEASE := 4,
  /// Request factsheet
  REQUEST_FACTSHEET := 5,
  /// Continue load transfer after an error
  REQUEST_CONTINUE_LOAD_TRANSFER := 6,
  /// Cancel the active request
  REQUEST_CANCEL := 7,
  /// Create or update a transport order
  REQUEST_TRANSPORT_ORDER := 8,
  /// Request door transit
  REQUEST_TRANSIT := 9,
  /// Request a signal
  REQUEST_SIGNAL := 10,
  /// Request an elevator
  REQUEST_ELEVATOR := 11,
  /// Request floor change
  REQUEST_CHANGE_FLOOR := 12,
  /// Request manual mode
  REQUEST_MANUAL_MODE := 13,
  /// Start charging
  REQUEST_START_CHARGE := 14,
  /// Stop charging
  REQUEST_STOP_CHARGE := 15
);
END_TYPE

{attribute 'qualified_only'}
// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      SessionPhaseEnum
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    Sequence phase of a session (charging device, elevator)
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
/// Sequence phase of a session (charging device, elevator)
TYPE SessionPhaseEnum :
(
  /// No session
  IDLE      := 0,
  /// Session opened (request delivered to the application)
  REQUESTED := 1,
  /// Session request finished
  GRANTED   := 2,
  /// Session is active (charging started, floor change finished ...)
  ACTIVE    := 3,
  /// Exit or stop finished, release expected
  EXITING   := 4,
  /// A request of the session failed
  FAILED    := 5
);
END_TYPE

// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      ChargingProcessData
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    Charging process reported by the charging device
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
/// Charging process reported by the charging device
TYPE ChargingProcessData :
STRUCT
  /// CHARGING, DONE or IDLE
  Charging     : ChargingProcessEnum := ChargingProcessEnum.IDLE;
  /// Temperature during charging
  Temperature  : LREAL;
  /// Charging rate
  ChargingRate : LREAL;
  /// Derating active
  Derating     : BOOL;
END_STRUCT
END_TYPE

// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      EndpointConfigData
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    Configuration of a client or server endpoint
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
/// Configuration of a client or server endpoint
TYPE EndpointConfigData :
STRUCT
  /// Interface name, first topic segment (e.g. lhs)
  InterfaceName   : STRING(32);
  /// Version segment of the topic
  TopicVersion    : STRING(16) := 'v1';
  /// Unique entity name (server: own name, client: name of the target entity)
  EntityName      : STRING(64);
  /// Serial number of the entity (server only)
  SerialNumber    : STRING(64);
  /// Manufacturer of the entity (server only)
  Manufacturer    : STRING(64);
  /// Protocol version written into the messages
  ProtocolVersion : STRING(16) := '0.9.0';
END_STRUCT
END_TYPE

// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      ErrorData
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    Error of an entity (common error object for all interfaces)
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
/// Error of an entity (common error object for all interfaces)
TYPE ErrorData :
STRUCT
  /// Type of the error
  ErrorType           : STRING(64);
  /// Level of the error
  ErrorLevel          : ErrorLevelEnum;
  /// Verbose description
  ErrorDescription    : STRING(255);
  /// Request that caused the error (optional)
  RequestId           : STRING(64);
  /// Point the error belongs to (0 = whole entity, not serialized)
  PointIndex          : DINT;
  /// Number of valid error references
  ErrorReferenceCount : DINT;
  /// Error references
  ErrorReferences     : ARRAY [1..M2XLibraryParameter.ERROR_REFERENCES_MAX] OF ErrorReferenceData;
END_STRUCT
END_TYPE

// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      ErrorReferenceData
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    Reference of an error (key/value pair)
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
/// Reference of an error (key/value pair)
TYPE ErrorReferenceData :
STRUCT
  /// Reference key (e.g. objectiveId)
  ReferenceKey   : STRING(64);
  /// Reference value
  ReferenceValue : STRING(255);
END_STRUCT
END_TYPE

// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      LoadHandlingUnitData
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    Load handling unit (LHU)
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
/// Load handling unit (LHU)
TYPE LoadHandlingUnitData :
STRUCT
  /// ID of the LHU (optional)
  LoadUnitId           : STRING(64);
  /// Type of the LHU, e.g. euro_pallet
  LoadHandlingUnitType : STRING(64);
  /// Weight is valid
  WeightValid          : BOOL;
  /// Weight of the load
  Weight               : LREAL;
  /// Height, width and length are valid
  DimensionsValid      : BOOL;
  /// Height (outer dimension)
  Height               : LREAL;
  /// Width (outer dimension)
  Width                : LREAL;
  /// Length (outer dimension)
  Length               : LREAL;
  /// Outer packaging (optional)
  OuterPackaging       : STRING(64);
  /// Symmetrical is valid
  SymmetricalValid     : BOOL;
  /// Orientation of the LHU is symmetrical
  Symmetrical          : BOOL;
END_STRUCT
END_TYPE

// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      MessageData
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    Message received from a transport
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
/// Message received from a transport
TYPE MessageData :
STRUCT
  /// Topic of the message
  Topic         : STRING(255);
  /// Length of the payload in bytes
  PayloadLength : UDINT;
  /// TRUE if the payload did not fit into the buffer (payload is empty then)
  Oversized     : BOOL;
  /// Payload
  Payload       : ARRAY [0..M2XLibraryParameter.MESSAGE_SIZE_MAX - 1] OF BYTE;
END_STRUCT
END_TYPE

// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      RequestData
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    One request
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
/// One request
TYPE RequestData :
STRUCT
  /// Type of the request
  RequestType        : RequestTypeEnum;
  /// Unique id of the request
  RequestId          : STRING(64);
  /// Additional information (optional)
  RequestDescription : STRING(255);
  /// Identity of the sender (M2X proposal, empty if not sent)
  SenderId           : STRING(64);
  /// Request parameters
  Parameters         : RequestParameterData;
END_STRUCT
END_TYPE

// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      RequestEntryData
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    Request entry of a server
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
/// Request entry of a server
TYPE RequestEntryData :
STRUCT
  /// Entry is used
  Used              : BOOL;
  /// Received request
  Request           : RequestData;
  /// Current status
  Status            : RequestStatusEnum;
  /// Result description written into the state
  ResultDescription : STRING(255);
  /// Point of the entity the request belongs to (1..POINTS_MAX)
  PointIndex        : DINT;
  /// Request was handed to the application
  Delivered         : BOOL;
  /// Arrival order
  Sequence          : UDINT;
  /// Time when the request reached FINISHED or FAILED
  FinalTime         : TIME;
END_STRUCT
END_TYPE

// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      RequestParameterData
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    Request parameters of all interfaces (empty string / NONE = parameter not set)
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
/// Request parameters of all interfaces (empty string / NONE = parameter not set)
TYPE RequestParameterData :
STRUCT
  /// Load handling: session id
  LoadHandlingSessionId    : STRING(64);
  /// Load handling: load handling point id
  LoadHandlingPointId      : STRING(64);
  /// Load handling / elevator: vehicle type
  VehicleType              : STRING(64);
  /// Load handling: PICK or DROP
  LoadAction               : LoadActionEnum;
  /// Load handling: load handling unit is set
  LoadHandlingUnitValid    : BOOL;
  /// Load handling: load handling unit
  LoadHandlingUnit         : LoadHandlingUnitData;
  /// Load handling: active load transfer device
  ActiveLoadTransferDevice : LoadTransferDeviceEnum;
  /// Door: door id
  DoorId                   : STRING(64);
  /// Door: requested door status
  DoorStatus               : DoorStatusEnum;
  /// Signaling device: signal id
  SignalId                 : STRING(64);
  /// Elevator: session id
  ElevatorSessionId        : STRING(64);
  /// Elevator: floor where the MR waits
  RequestedFloor           : STRING(64);
  /// Elevator: intended target floor
  IntendedTargetFloor      : STRING(64);
  /// Elevator: target floor of requestChangeFloor
  TargetFloor              : STRING(64);
  /// Elevator: operation mode of requestManualMode
  OperationMode            : OperationModeEnum;
  /// Charging device: session id
  ChargingSessionId        : STRING(64);
  /// Transport order: transport order id (requestCancel)
  TransportOrderId         : STRING(64);
  /// Transport order: IsCanceled is set
  IsCanceledValid          : BOOL;
  /// Transport order: cancel flag
  IsCanceled               : BOOL;
END_STRUCT
END_TYPE

// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      RequestStateData
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    Request state as seen by a client
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
/// Request state as seen by a client
TYPE RequestStateData :
STRUCT
  /// Entry is used
  Used              : BOOL;
  /// Id of the request
  RequestId         : STRING(64);
  /// Type of the request
  RequestType       : RequestTypeEnum;
  /// Status reported by the server
  RequestStatus     : RequestStatusEnum;
  /// Result description reported by the server
  ResultDescription : STRING(255);
  /// Time when the request was sent
  SendTime          : TIME;
END_STRUCT
END_TYPE

// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      SessionData
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    Session of a charging device or elevator (server)
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
/// Session of a charging device or elevator (server)
TYPE SessionData :
STRUCT
  /// Sequence phase
  Phase     : SessionPhaseEnum;
  /// Session id
  SessionId : STRING(64);
  /// Sender of the session
  SenderId  : STRING(64);
END_STRUCT
END_TYPE

// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
