/// M2X client of a load handling station (MR/FM side)
FUNCTION_BLOCK LhsClientFB EXTENDS ClientBaseFB
// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      LhsClientFB
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    M2X client of a load handling station (MR/FM side)
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
VAR_OUTPUT
  /// Number of load handling points in the last state
  PointCount : DINT;
  /// Load handling points of the last state
  Points     : ARRAY [1..M2XLibraryParameter.POINTS_MAX] OF LhpStateData;
END_VAR

ST.xhtml:
 // Rising edge: send
 IF (( Execute ) AND ( NOT _execute ))
 THEN
   Done              := FALSE;
   Error             := FALSE;
   ErrorText         := '';
   Status            := RequestStatusEnum.NONE;
   ResultDescription := '';
   RequestId         := Client.SendRequest(RequestType := RequestType, Description := Description, Parameters := Parameters);
   IF ( RequestId = '' )
   THEN
     Error     := TRUE;
     ErrorText := 'SEND_FAILED';
   ELSE
     Busy := TRUE;
    _timer(IN := FALSE);
   END_IF
 END_IF
_execute := Execute;

 IF ( Busy )
 THEN
   Status            := Client.GetRequestStatus(RequestId := RequestId);
   ResultDescription := Client.GetResultDescription(RequestId := RequestId);
  _timer(IN := TRUE, PT := Timeout);
   IF ( Status = RequestStatusEnum.FINISHED )
   THEN
     Done := TRUE;
     Busy := FALSE;
   ELSIF ( Status = RequestStatusEnum.FAILED )
   THEN
     Error     := TRUE;
     ErrorText := 'REQUEST_FAILED';
     Busy      := FALSE;
   ELSIF ( _timer.Q )
   THEN
     Error     := TRUE;
     ErrorText := 'TIMEOUT';
     Busy      := FALSE;
   END_IF
 END_IF

 // Outputs are reset with Execute = FALSE
 IF (( NOT Execute ) AND ( NOT Busy ))
 THEN
   Done  := FALSE;
   Error := FALSE;
 END_IF

