//
// -------------------------------------------------------------------------
VAR_INPUT
  /// Topic filter
  Filter : STRING(255);
  /// Topic
  Topic  : STRING(255);
END_VAR
VAR
  /// Position in the filter
 _fi        : UDINT;
  /// Position in the topic
 _ti        : UDINT;
  /// Length of the filter
 _filterLen : UDINT;
  /// Length of the topic
 _topicLen  : UDINT;
END_VAR

