FOR _idx := ObjectToken + 1 TO _tokenCount - 1 DO IF ( _tokens[_idx].StartPos >= _tokens[ObjectToken].EndPos ) THEN RETURN; END_IF IF ( _tokens[_idx].Parent = ObjectToken ) THEN IF ( _count = Index ) THEN GetObjectKey := _idx; RETURN; END_IF _count := _count + 1; END_IF END_FOR

