/// String value of a token (unescaped, max. 255 bytes; raw text for primitives)
VAR_INPUT
  /// Token
  Token : DINT;
END_VAR
VAR
  /// Result
 _result  : STRING(255);
  /// Pointer to the result
 _pResult : POINTER TO BYTE;
  /// Write position
 _n       : DINT;
  /// Read position
 _pos     : DINT;
  /// End position
 _end     : DINT;
  /// Current character
 _c       : BYTE;
  /// Unicode code point of \uXXXX
 _code    : UDINT;
  /// Hex digit counter
