InterfaceAsPlainText.xhtml:
METHOD PRIVATE AppendByte
/// Appends one byte
VAR_INPUT
  /// Byte to append
  Value : BYTE;
END_VAR

ST.xhtml:
AppendByte(Value := 34);

WHILE (( _idx < 255 ) AND ( Text[_idx] <> 0 )) DO
 _c := Text[_idx];
  CASE _c OF
    34, 92:
      AppendByte(Value := 92);
      AppendByte(Value := _c);
    8:
      AppendByte(Value := 92);
      AppendByte(Value := 98);
    9:
      AppendByte(Value := 92);
      AppendByte(Value := 116);
    10:
      AppendByte(Value := 92);
      AppendByte(Value := 110);
    12:
      AppendByte(Value := 92);
      AppendByte(Value := 102);
    13:
      AppendByte(Value := 92);
      AppendByte(Value := 114);
  ELSE
    IF ( _c < 32 )
    THEN
      // other control characters as \u00XX
      AppendText(Text := '\u00');
      AppendByte(Value := HexDigit(_c / 16));
      AppendByte(Value := HexDigit(_c MOD 16));
    ELSE
      AppendByte(Value := _c);
    END_IF
  END_CASE
 _idx := _idx + 1;
END_WHILE

AppendByte(Value := 34);

