ST.xhtml:
IF ( _depth < M2XLibraryParameter.JSON_DEPTH_MAX )
THEN
 _depth         := _depth + 1;
 _first[_depth] := TRUE;
ELSE
 _overflow := TRUE;
END_IF

_length    := 0;
_overflow  := FALSE;
_depth     := 0;
_afterKey  := FALSE;
_first[0]  := TRUE;
_buffer[0] := 0;

BeforeValue();
IF ( Value )
THEN
  AppendText(Text := 'true');
ELSE
  AppendText(Text := 'false');
END_IF

