//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
VAR
  /// Connected transports
 _clients      : ARRAY [1..M2XLibraryParameter.MOCK_CLIENTS_MAX] OF POINTER TO MockTransportFB;
  /// Retained messages
 _retained     : ARRAY [1..M2XLibraryParameter.MOCK_RETAINED_MAX] OF MessageData;
  /// Retained message slot is used
 _retainedUsed : ARRAY [1..M2XLibraryParameter.MOCK_RETAINED_MAX] OF BOOL;
  /// Number of published messages
 _published    : UDINT;
END_VAR

ST.xhtml:
IF (( Enable ) AND ( NOT _connected ) AND ( NOT _lost ) AND ( Broker <> 0 ))
THEN
 _connected := Broker^.Register(Client := THIS);
ELSIF (( NOT Enable ) AND ( _connected ))
THEN
  Broker^.Unregister(Client := THIS);
 _connected := FALSE;
END_IF

IF ( NOT Enable )
THEN
 _lost              := FALSE;
 _subscriptionCount := 0;
 _count             := 0;
END_IF

 FOR _idx := 1 TO _subscriptionCount
 DO
   IF ( TopicMatches(Filter := _subscriptions[_idx], Topic := Topic) )
   THEN
    _match := TRUE;
     EXIT;
   END_IF
 END_FOR

 IF ( NOT _match )
 THEN
   RETURN;
 END_IF

 IF ( _count >= M2XLibraryParameter.MESSAGE_QUEUE_MAX )
 THEN
   Overflows := Overflows + 1;
   RETURN;
 END_IF

_slot := ( _head + _count ) MOD M2XLibraryParameter.MESSAGE_QUEUE_MAX;
_queue[_slot].Topic := Topic;
 IF ( PayloadLength > SIZEOF(_queue[_slot].Payload) )
 THEN
  _queue[_slot].Oversized     := TRUE;
  _queue[_slot].PayloadLength := 0;
 ELSE
  _queue[_slot].Oversized     := FALSE;
  _queue[_slot].PayloadLength := PayloadLength;
   SysDepMemCpy(pDest := ADR(_queue[_slot].Payload), pSrc := pPayload, DataLen := PayloadLength);
 END_IF
_count   := _count + 1;
 Deliver := TRUE;

InterfaceAsPlainText.xhtml:
METHOD Deliver : BOOL
/// Called by the broker: queues the message if a subscription matches
VAR_INPUT
  /// Topic
  Topic         : STRING(255);
  /// Payload
  pPayload      : POINTER TO BYTE;
  /// Length of the payload
  PayloadLength : UDINT;
END_VAR
VAR
  /// Subscription index
 _idx   : DINT;
  /// Subscription matches
 _match : BOOL;
  /// Queue slot
 _slot  : UDINT;
END_VAR

ST.xhtml:
IF (( NOT _connected ) OR ( Broker = 0 ))
THEN
  RETURN;
END_IF

Publish := Broker^.Publish(Topic := Topic, pPayload := pPayload, PayloadLength := PayloadLength, RetainFlag := RetainFlag);

InterfaceAsPlainText.xhtml:
METHOD Publish : BOOL
/// Publishes a message
VAR_INPUT
  /// Topic
  Topic         : STRING(255);
  /// Payload
  pPayload      : POINTER TO BYTE;
  /// Length of the payload
  PayloadLength : UDINT;
  /// Retain flag
  RetainFlag        : BOOL;
END_VAR

ST.xhtml:
 IF ( _count = 0 )
 THEN
   RETURN;
 END_IF

 Message := _queue[_head];
_head    := ( _head + 1 ) MOD M2XLibraryParameter.MESSAGE_QUEUE_MAX;
_count   := _count - 1;
 Receive := TRUE;

InterfaceAsPlainText.xhtml:
METHOD Receive : BOOL
/// Reads the next received message (FALSE if none)
VAR_IN_OUT
  /// Received message
  Message : MessageData;
END_VAR

ST.xhtml:
 IF ( PayloadLength > M2XLibraryParameter.WILL_SIZE_MAX )
 THEN
   RETURN;
 END_IF

_willTopic  := Topic;
_willLength := PayloadLength;
_willRetain := RetainFlag;
_willSet    := TRUE;
 SysDepMemCpy(pDest := ADR(_willPayload), pSrc := pPayload, DataLen := PayloadLength);
 SetLastWill := TRUE;

InterfaceAsPlainText.xhtml:
METHOD SetLastWill : BOOL
/// Stores the last will
VAR_INPUT
  /// Topic
  Topic         : STRING(255);
  /// Payload
  pPayload      : POINTER TO BYTE;
  /// Length of the payload
  PayloadLength : UDINT;
  /// Retain flag
  RetainFlag        : BOOL;
END_VAR

ST.xhtml:
 IF ( NOT _connected )
 THEN
   RETURN;
 END_IF

 Broker^.Unregister(Client := THIS);
_connected := FALSE;
_lost      := TRUE;

 IF ( _willSet )
 THEN
   Broker^.Publish(Topic := _willTopic, pPayload := ADR(_willPayload), PayloadLength := _willLength, RetainFlag := _willRetain);
 END_IF

 IF (( NOT _connected ) OR ( Broker = 0 ))
 THEN
   RETURN;
 END_IF

 FOR _idx := 1 TO _subscriptionCount
 DO
   IF ( _subscriptions[_idx] = Topic )
   THEN
     Subscribe := TRUE;
     RETURN;
   END_IF
 END_FOR

 IF ( _subscriptionCount >= M2XLibraryParameter.SUBSCRIPTIONS_MAX )
 THEN
   RETURN;
 END_IF

_subscriptionCount                 := _subscriptionCount + 1;
_subscriptions[_subscriptionCount] := Topic;
 Broker^.DeliverRetained(Client := THIS, Filter := Topic);
 Subscribe := TRUE;

InterfaceAsPlainText.xhtml:
METHOD Subscribe : BOOL
/// Subscribes to a topic filter (retained messages are delivered immediately)
VAR_INPUT
  /// Topic filter
  Topic : STRING(255);
END_VAR
VAR
  /// Subscription index
 _idx : DINT;
END_VAR

/// Transport connected to a MockBrokerFB (tests without MQTT)
FUNCTION_BLOCK MockTransportFB IMPLEMENTS ITransport
// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      MockTransportFB
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    Transport connected to a MockBrokerFB (tests without MQTT)
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
VAR_INPUT
  /// Connect to the broker
  Enable : BOOL;
  /// Broker
  Broker : POINTER TO MockBrokerFB;
END_VAR
VAR_OUTPUT
  /// Number of lost messages because the queue was full
  Overflows : UDINT;
END_VAR
VAR
  /// Connected to the broker
 _connected         : BOOL;
  /// Connection loss was simulated (reconnect only after Enable = FALSE)
 _lost              : BOOL;
  /// Subscribed topic filters
 _subscriptions     : ARRAY [1..M2XLibraryParameter.SUBSCRIPTIONS_MAX] OF STRING(255);
  /// Number of subscriptions
 _subscriptionCount : DINT;
  /// Receive queue
 _queue             : ARRAY [0..M2XLibraryParameter.MESSAGE_QUEUE_MAX - 1] OF MessageData;
  /// Index of the oldest message
 _head              : UDINT;
  /// Number of queued messages
 _count             : UDINT;
  /// Topic of the last will
 _willTopic         : STRING(255);
  /// Payload of the last will
 _willPayload       : ARRAY [0..M2XLibraryParameter.WILL_SIZE_MAX - 1] OF BYTE;
  /// Length of the last will payload
 _willLength        : UDINT;
  /// Retain flag of the last will
 _willRetain        : BOOL;
  /// Last will is set
 _willSet           : BOOL;
END_VAR

ST.xhtml:
_client(Enable := Enable, Config := Config);
 Error   := _client.Error;
 ErrorId := _client.ErrorId;

InterfaceAsPlainText.xhtml:
METHOD Publish : BOOL
/// Publishes a message
VAR_INPUT
  /// Topic
  Topic         : STRING(255);
  /// Payload
  pPayload      : POINTER TO BYTE;
  /// Length of the payload
  PayloadLength : UDINT;
  /// Retain flag
  RetainFlag        : BOOL;
END_VAR

METHOD Receive : BOOL
/// Reads the next received message (FALSE if none)
VAR_IN_OUT
  /// Received message
  Message : MessageData;
END_VAR

METHOD SetLastWill : BOOL
/// Sets the last will (used at the next connect)
VAR_INPUT
  /// Topic
  Topic         : STRING(255);
  /// Payload
  pPayload      : POINTER TO BYTE;
  /// Length of the payload
  PayloadLength : UDINT;
  /// Retain flag
  RetainFlag        : BOOL;
END_VAR

METHOD Subscribe : BOOL
/// Subscribes to a topic filter
VAR_INPUT
  /// Topic filter
  Topic : STRING(255);
END_VAR

/// MQTT transport (uses the system dependent MQTT client)
FUNCTION_BLOCK MqttTransportFB IMPLEMENTS ITransport
// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      MqttTransportFB
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    MQTT transport (uses the system dependent MQTT client)
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
VAR_INPUT
  /// Connect to the broker
  Enable : BOOL;
  /// MQTT configuration
  Config : SysDepMqttConfig;
  /// Quality of service of publish and subscribe
  QoS    : SysDepMqttQoS := SysDepMqttQoS.AT_LEAST_ONCE;
END_VAR
VAR_OUTPUT
  /// MQTT client reports an error
  Error   : BOOL;
  /// Error code of the platform
  ErrorId : UDINT;
END_VAR
VAR
  /// System dependent MQTT client
 _client : SysDepMqttClientFB;
END_VAR

{attribute 'qualified_only'}
// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      M2XLibraryConstants
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    Constants of the M2X protocol
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
/// Constants of the M2X protocol
VAR_GLOBAL CONSTANT
  /// Implemented M2X protocol version
  PROTOCOL_VERSION            : STRING(16) := '0.9.0';
  /// Version segment of the topic
  TOPIC_VERSION               : STRING(16) := 'v1';
  /// Interface name of the load handling interface
  INTERFACE_LHS               : STRING(32) := 'lhs';
  /// Interface name of the transport order interface
  INTERFACE_ORDER             : STRING(32) := 'order';
  /// Interface name of the door interface
  INTERFACE_DOOR              : STRING(32) := 'door';
  /// Interface name of the signaling device interface
  INTERFACE_SIGNALING_DEVICE  : STRING(32) := 'signal_light';
  /// Interface name of the elevator interface
  INTERFACE_ELEVATOR          : STRING(32) := 'elevator';
  /// Interface name of the charging device interface
  INTERFACE_CHARGING_DEVICE   : STRING(32) := 'charging_device';
  /// Topic for requests (one generic request topic per entity)
  TOPIC_REQUEST               : STRING(32) := 'request';
  /// Topic for the state
  TOPIC_STATE                 : STRING(32) := 'state';
  /// Topic for the factsheet
  TOPIC_FACTSHEET             : STRING(32) := 'factsheet';
  /// Error type: request type not supported by the entity
  ERR_REQUEST_NOT_SUPPORTED   : STRING(64) := 'REQUEST_NOT_SUPPORTED';
  /// Error type: the sender already has an active request
  ERR_REQUEST_ALREADY_ACTIVE  : STRING(64) := 'REQUEST_ALREADY_ACTIVE';
  /// Error type: a request parameter is missing or invalid
  ERR_INVALID_PARAMETER       : STRING(64) := 'INVALID_REQUEST_PARAMETER';
  /// Error type: the request is not allowed in the current sequence step
  ERR_REQUEST_SEQUENCE        : STRING(64) := 'REQUEST_SEQUENCE_ERROR';
  /// Error type: the received message could not be parsed
  ERR_INVALID_MESSAGE         : STRING(64) := 'INVALID_MESSAGE';
  /// Error type: no free request entry
  ERR_REQUEST_TABLE_FULL      : STRING(64) := 'REQUEST_TABLE_FULL';
  /// Error type: error during execution (predefined by the spec)
  ERR_DURING_EXECUTION        : STRING(64) := 'ERROR_DURING_EXECUTION';
  /// Error type: inconsistent transport order data (predefined by the spec)
  ERR_IN_VALIDATION           : STRING(64) := 'ERROR_IN_VALIDATION';
  /// Error type: objective already finished (predefined by the spec)
  ERR_OBJECTIVE_FINISHED      : STRING(64) := 'OBJECTIVE_ALREADY_FINISHED';
  /// Error type: objective already in execution (predefined by the spec)
  ERR_OBJECTIVE_IN_EXECUTION  : STRING(64) := 'OBJECTIVE_IN_EXECUTION';
  /// Error type: non-contiguous sequenceId (predefined by the spec)
  ERR_SEQUENCE_ID             : STRING(64) := 'SEQUENCE_ID_NON_CONTIGUOUS';
END_VAR

{attribute 'qualified_only'}
// -------------------------------------------------------------------------
//  M2X Library
// -------------------------------------------------------------------------
//
//  Object:      M2XLibraryParameter
//  Author:      Thorsten Brach
//  Date:        2026-10-15
//
//  Description:
//    Library parameters (sizes and timing) of the M2X library
//
//  Copyright:
//    (C) 2026 Thorsten Brach. All rights reserved
//             Licensed under the MIT License.
//
//  Disclaimer:
//    This project is provided without any guarantee and can be used for
//    private and commercial purposes. Any use is at the user's
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
/// Library parameters (sizes and timing) of the M2X library
VAR_GLOBAL CONSTANT
  /// Maximum size of one message (request, state or factsheet) in bytes
  MESSAGE_SIZE_MAX     : UDINT := 8192;
  /// Maximum number of messages buffered per transport
  MESSAGE_QUEUE_MAX    : UDINT := 8;
  /// Maximum size of the MQTT last will payload in bytes
  WILL_SIZE_MAX        : UDINT := 1024;
  /// Maximum number of JSON tokens of one message
  JSON_TOKEN_MAX       : DINT  := 512;
  /// Maximum nesting depth of a written JSON message
  JSON_DEPTH_MAX       : DINT  := 16;
  /// Maximum number of request entries of a server (all senders, all points)
  REQUEST_ENTRIES_MAX  : DINT  := 16;
  /// Maximum number of active errors of an endpoint
  ERRORS_MAX           : DINT  := 8;
  /// Maximum number of references of one error
  ERROR_REFERENCES_MAX : DINT  := 4;
  /// Maximum number of points of a server (load handling points, elevators of a group)
  POINTS_MAX           : DINT  := 4;
  /// Maximum number of signals of a signaling device
  SIGNALS_MAX          : DINT  := 8;
  /// Maximum number of objectives of a transport order
  OBJECTIVES_MAX       : DINT  := 16;
  /// Maximum number of requests tracked by a client
  CLIENT_REQUESTS_MAX  : DINT  := 16;
  /// Maximum number of subscriptions of a mock transport
  SUBSCRIPTIONS_MAX    : DINT  := 8;
  /// Maximum number of transports connected to a mock broker
  MOCK_CLIENTS_MAX     : DINT  := 16;
  /// Maximum number of retained messages of a mock broker
  MOCK_RETAINED_MAX    : DINT  := 16;
  /// Interval for the cyclic state message (spec: at least every 30 s)
  STATE_INTERVAL       : TIME  := T#30S;
  /// Time a finished or failed request stays in the state message
  REQUEST_RETENTION    : TIME  := T#60S;
END_VAR

METHOD Publish : BOOL
/// Publishes a message
VAR_INPUT
  /// Topic
  Topic         : STRING(255);
  /// Payload
  pPayload      : POINTER TO BYTE;
  /// Length of the payload
  PayloadLength : UDINT;
  /// Retain flag
  RetainFlag        : BOOL;
END_VAR

METHOD Receive : BOOL
/// Reads the next received message (FALSE if none)
VAR_IN_OUT
  /// Received message
  Message : MessageData;
END_VAR

METHOD SetLastWill : BOOL
/// Sets the last will (published by the broker on an unexpected disconnect)
VAR_INPUT
  /// Topic
  Topic         : STRING(255);
  /// Payload
  pPayload      : POINTER TO BYTE;
  /// Length of the payload
  PayloadLength : UDINT;
  /// Retain flag
  RetainFlag        : BOOL;
END_VAR

METHOD Subscribe : BOOL
/// Subscribes to a topic filter
VAR_INPUT
  /// Topic filter
  Topic : STRING(255);
END_VAR

